INSERT INTO ghostdesk.case_versions(version_id, case_id, package, published) VALUES ('hotel-404-v1', 'hotel-404', $case${"schemaVersion":1,"engineVersion":"ghostdesk-core-1","caseId":"hotel-404","versionId":"hotel-404-v1","title":"자정의 404호","description":"폐쇄된 호텔 4층에서 문이 열렸다. 프런트 화면에는 체크아웃한 손님이 다시 나타나는데…","estimatedMinutes":12,"contentWarning":"허구의 사건입니다. 긴장감 있는 상황·실종 암시가 있지만 잔혹한 묘사나 점프 스케어는 없습니다.","files":[{"id":"hotel-404-f0","type":"TEXT","title":"야간_인계.txt","parentId":null,"visible":true,"text":"야간 인계 / 프런트 담당 서린\n\n00:04, 폐쇄된 4층의 404호 앞에 흰 형체가 지나갔습니다. 화면에는 LIVE 표시가 켜져 있었어요. 그런데 객실 키는 모두 프런트에 있습니다.\n\n실제로 열린 문부터 확인해 주세요. 비공개 기록의 암호는 마지막 개방 장치가 연결된 문 번호입니다. 영문과 숫자 네 글자. 표시 화면의 객실명이 아니라 시설 장치 대장의 연결 위치를 사용합니다.\n\n시설 기록과 화면 캡처 설명을 바탕으로 무엇이 움직였는지 결론을 내려 주세요.","clueId":"hotel-404-c0"},{"id":"hotel-404-f1","type":"TEXT","title":"출입_이벤트.log","parentId":null,"visible":true,"text":"호텔 출입 제어기 / 오늘의 원본 이벤트\n\n00:03:58  장치 D-07  원격 개방 요청\n00:04:00  장치 D-07  개방 성공\n00:04:12  장치 D-07  자동 잠금\n\n오늘 4층 객실 장치 D-41~D-48의 개방 이벤트는 0건입니다.\n\n주의: 프런트에 보이는 카메라 이름은 출입 장치의 위치를 뜻하지 않습니다.","clueId":"hotel-404-c1"},{"id":"hotel-404-f2","type":"TEXT","title":"시설_장치대장.txt","parentId":null,"visible":true,"text":"시설팀 장치 대장 / 개보수 반영본\n\nD-03 → 0103 / 1층 창고\nD-07 → B204 / 지하 2층 세탁물 통로\nD-41 → 0401 / 4층 401호\nD-44 → 0404 / 4층 404호\n\n지하 통로는 배송 로봇 R17도 이용합니다. 층수 표시의 B는 지하층을 뜻하며 암호에 포함합니다.","clueId":"hotel-404-c2"},{"id":"hotel-404-f3","type":"TEXT","title":"화면_캡처_설명.txt","parentId":null,"visible":true,"text":"프런트 모니터 캡처를 문자로 기록함\n\n좌상단: CAM-404 / LIVE\n우하단 원본 프레임: 06-12 14:32 / F-8821\n복도 우측: 공사 중 노란 덮개\n흰 형체: 접힌 시트 더미가 카트 위를 지나가는 모습\n\n오늘은 09-28. 노란 덮개는 6월 보수공사가 끝나면서 철거됐습니다. 화면 위의 LIVE는 프런트 프로그램이 붙이는 표지입니다.","clueId":"hotel-404-c3"},{"id":"hotel-404-f4","type":"TEXT","title":"재생_진단서.txt","parentId":"hotel-404-vault","visible":false,"text":"CAM-404 재생 진단\n\n실시간 입력: 연결 끊김\n대체 소스: 06-12 보수공사 녹화\n재생 방식: 마지막 정상 영상 반복\n화면 위 LIVE 표지: 연결 상태와 무관하게 고정 표시\n\n오늘 00:04에도 F-8821 프레임이 재생됐습니다. 고정 표지 때문에 프런트 직원이 현재 영상으로 오인했습니다.","clueId":"hotel-404-c4"},{"id":"hotel-404-f5","type":"TEXT","title":"배송_완료증.txt","parentId":"hotel-404-vault","visible":false,"text":"세탁 배송 로봇 R17\n\n작업 번호: LINEN-0928\n00:04:00 B204 개방 신호 확인\n00:04:08 지하 세탁물 통로 통과\n00:06:21 세탁실 도착 / 시트 12묶음 인계\n\n오늘 4층 운행 명령 없음. 객실 손님 인식 기록 없음.\n\n프런트의 오래된 영상과 오늘의 문 개방은 별개의 사건이었습니다.","clueId":"hotel-404-c5"},{"id":"hotel-404-chat","type":"CHAT_LINK","title":"메신저","parentId":null,"visible":true,"text":""},{"id":"hotel-404-vault","type":"FOLDER","title":"비공개 기록","parentId":null,"visible":true,"text":"남은 기록을 대조해 결론을 완성하세요.","puzzleId":"hotel-404-p1"}],"clues":[{"id":"hotel-404-c0","title":"닫힌 4층","description":"4층 객실 키는 프런트에 있고 마지막 개방 장치의 실제 연결 위치가 암호다."},{"id":"hotel-404-c1","title":"열린 것은 D-07","description":"00:04 개방 성공은 D-07 한 건. 4층 객실 장치는 열리지 않았다."},{"id":"hotel-404-c2","title":"D-07의 실제 위치","description":"D-07은 404호가 아니라 지하 세탁물 통로 B204에 연결됐다."},{"id":"hotel-404-c3","title":"화면 속 날짜는 6월","description":"원본 프레임 날짜와 철거된 덮개가 오래된 영상을 가리킨다."},{"id":"hotel-404-c4","title":"반복된 보수공사 영상","description":"실시간 카메라는 끊겼고 6월 녹화가 반복됐다. LIVE 표지는 고정이었다."},{"id":"hotel-404-c5","title":"지하를 지난 세탁 로봇","description":"오늘 움직인 것은 지하 배송 로봇이며 4층 방문 기록은 없다."}],"puzzles":[{"id":"hotel-404-p1","title":"마지막으로 열린 장치의 실제 문 번호를 입력하세요.","answer":"B204","ignoreCase":true,"hints":["출입 이벤트의 장치 번호와 시설 장치 대장을 연결하세요.","CAM-404는 카메라 이름입니다. 실제 개방 장치는 D-07입니다.","D-07의 연결 위치는 지하 세탁물 통로입니다. 영문도 포함하세요.","정답은 B204입니다."]}],"messages":[{"id":"hotel-404-m0","author":"서린","time":"00:07","text":"키는 전부 여기 있어. 그럼 저 복도에 있는 건 누구지?","initial":true},{"id":"hotel-404-m1","author":"서린","time":"00:08","text":"LIVE라는 글자를 믿어도 되는 걸까?","initial":true},{"id":"hotel-404-m2","author":"시설팀","time":"00:09","text":"카메라 이름과 출입 제어기 번호를 혼동하지 마세요. 대장을 다시 보냈습니다.","initial":false},{"id":"hotel-404-m3","author":"서린","time":"00:11","text":"진단서가 열렸네. 흰 형체보다 화면 구석의 날짜가 더 중요했구나.","initial":false}],"rules":[{"id":"hotel-404-unlock","priority":10,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"hotel-404-p1"},"then":[{"type":"REVEAL_FILE","id":"hotel-404-f4"},{"type":"REVEAL_FILE","id":"hotel-404-f5"},{"type":"APPEND_MESSAGE","id":"hotel-404-m3"}]},{"id":"hotel-404-timer","priority":20,"once":true,"when":{"type":"FILE_READ","id":"hotel-404-f1"},"then":[{"type":"START_TIMER","id":"hotel-404-t1","durationMs":1800}]},{"id":"hotel-404-reply","priority":30,"once":true,"when":{"type":"TIMER_REACHED","id":"hotel-404-t1"},"then":[{"type":"APPEND_MESSAGE","id":"hotel-404-m2"}]}],"endings":[{"id":"hotel-404-good","title":"유령은 화면 밖에 없었다","text":"404호에서 돌아온 손님은 없었습니다. 실시간 연결이 끊긴 카메라가 6월의 세탁물 영상을 반복했고 LIVE 표지가 그 위에 남아 있었습니다.\n\n같은 시각 실제로 열린 D-07은 지하 B204였습니다. 배송 완료증은 세탁 로봇 R17이 그 문을 통과했음을 확인합니다.\n\n서린은 모니터의 LIVE 스티커를 떼고 쪽지를 붙였습니다. “연결 확인 후 판단할 것.” 복도는 다시 조용해졌습니다.","revisitable":false},{"id":"hotel-404-retry","title":"객실 번호가 만든 유령","text":"CAM-404라는 이름과 LIVE 표시만으로 손님이 돌아왔다고 판단했습니다. 하지만 화면의 원본 날짜와 출입 장치 번호가 맞지 않습니다.\n\n재생 진단서와 배송 완료증을 함께 확인하고 다시 결론을 내려 주세요.","revisitable":true}],"hypotheses":[{"id":"hotel-404-truth","label":"옛 영상이 반복됐고, 실제로 열린 문은 지하 배송 통로였다.","endingId":"hotel-404-good","requiredClues":["hotel-404-c1","hotel-404-c4","hotel-404-c5"]},{"id":"hotel-404-guess","label":"체크아웃한 손님이 404호로 몰래 돌아왔다.","endingId":"hotel-404-retry","requiredClues":[]}]}$case$::jsonb, true);
INSERT INTO ghostdesk.case_versions(version_id, case_id, package, published) VALUES ('auction-seven-v1', 'auction-seven', $case${"schemaVersion":1,"engineVersion":"ghostdesk-core-1","caseId":"auction-seven","versionId":"auction-seven-v1","title":"낙찰 7초 전","description":"최고가를 부른 MOTH가 낙찰 직전 사라졌다. 화면에 남은 승자와 봉인된 입찰 원장이 서로 다르다.","estimatedMinutes":15,"contentWarning":"허구의 사건입니다. 긴장감 있는 상황·실종 암시가 있지만 잔혹한 묘사나 점프 스케어는 없습니다.","files":[{"id":"auction-seven-f0","type":"TEXT","title":"운영자_요청.txt","parentId":null,"visible":true,"text":"밤의 경매 / LOT-27 “푸른 궤도”\n\n종료 7초 전, MOTH가 접속을 끊었습니다. 전광판에는 아직 MOTH가 최고가로 표시됩니다. ORBIT는 자신이 진짜 낙찰자라고 주장하고 있어요.\n\n봉인 원장의 암호는 이번 물품의 최종 유효 최고 입찰자 닉네임입니다. 가격만 보지 말고 입찰 번호로 취소 요청을 반영하세요.\n\n마감 이후 입찰은 무효입니다. 가격이 같으면 접수 순번이 빠른 사람이 우선입니다. 대소문자는 구분하지 않습니다.","clueId":"auction-seven-c0"},{"id":"auction-seven-f1","type":"TEXT","title":"입찰_접수표.csv","parentId":null,"visible":true,"text":"LOT-27 / 마감 접수 순번 120까지 유효\n단위: 만 원 / 시간 표시는 참고용\n\n순번 115 / B-71 / ORBIT / 240\n순번 116 / B-72 / MOTH  / 310\n순번 118 / B-73 / LARK  / 240\n순번 120 / B-74 / PEARL / 235\n순번 121 / B-75 / MOTH  / 400\n\n화면 가격은 마지막 수신 값이며 최종 낙찰 처리가 아닙니다.","clueId":"auction-seven-c1"},{"id":"auction-seven-f2","type":"TEXT","title":"취소_요청함.txt","parentId":null,"visible":true,"text":"유효 취소 접수 / 마감 전 처리 완료\n\nC-19 → 입찰 B-72 전액 취소 / 본인 확인 완료\nC-20 → 다른 물품 LOT-11의 입찰 X-04 취소\n\n취소 대상은 닉네임 전체가 아니라 개별 입찰 번호입니다.\nMOTH의 접속 종료 자체는 입찰 취소 근거가 아닙니다.","clueId":"auction-seven-c2"},{"id":"auction-seven-f3","type":"TEXT","title":"경매_규칙.txt","parentId":null,"visible":true,"text":"낙찰 판정 순서\n\n1. 현재 물품 LOT-27만 본다.\n2. 접수 순번 120 뒤에 들어온 입찰을 제외한다.\n3. 유효 취소 접수에 적힌 입찰 번호를 제외한다.\n4. 남은 입찰 중 가격이 가장 높은 것을 고른다.\n5. 같은 가격이면 접수 순번이 빠른 입찰을 고른다.\n\n전광판의 순위는 지연될 수 있습니다. 낙찰 확정서의 입찰 번호가 최종 근거입니다.","clueId":"auction-seven-c3"},{"id":"auction-seven-f4","type":"TEXT","title":"낙찰_확정서.txt","parentId":"auction-seven-vault","visible":false,"text":"LOT-27 봉인 원장 / 검증 완료\n\n유효 최고가: 240만 원\n선정 입찰: B-71\n낙찰자: ORBIT\n동률 제외: B-73 / 더 늦은 접수\n취소 제외: B-72\n마감 뒤 제외: B-75\n\n확정서는 경매 종료 뒤 생성됐습니다. 접수표·취소 접수·경매 규칙을 모두 반영한 결과입니다.","clueId":"auction-seven-c4"},{"id":"auction-seven-f5","type":"TEXT","title":"전광판_갱신기록.log","parentId":"auction-seven-vault","visible":false,"text":"전광판 표시 기록\n\n마지막 반영: B-72 / MOTH / 310\n취소 알림 C-19: 전광판 대기열에 남음\n종료 뒤 화면 잠금: 이전 최고가 유지\n\n결제 요청 생성: B-71 / ORBIT\nMOTH에게 생성된 결제 요청: 없음\n\n빈 자리는 음모가 아니라 표시 지연을 남겼습니다.","clueId":"auction-seven-c5"},{"id":"auction-seven-chat","type":"CHAT_LINK","title":"메신저","parentId":null,"visible":true,"text":""},{"id":"auction-seven-vault","type":"FOLDER","title":"비공개 기록","parentId":null,"visible":true,"text":"남은 기록을 대조해 결론을 완성하세요.","puzzleId":"auction-seven-p1"}],"clues":[{"id":"auction-seven-c0","title":"원장 개방 규칙","description":"취소·마감·동률 우선순위까지 적용한 낙찰자의 닉네임이 암호다."},{"id":"auction-seven-c1","title":"입찰 접수 순번","description":"ORBIT와 LARK는 240으로 동률. MOTH의 400은 마감 뒤 접수됐다."},{"id":"auction-seven-c2","title":"B-72 취소 완료","description":"MOTH의 310만 원 입찰 B-72는 마감 전에 취소됐다."},{"id":"auction-seven-c3","title":"동률은 먼저 접수한 쪽","description":"가격이 같으면 접수 순번이 빠른 입찰이 우선한다."},{"id":"auction-seven-c4","title":"B-71의 확정 낙찰","description":"봉인 원장은 ORBIT의 B-71을 최종 낙찰로 확정했다."},{"id":"auction-seven-c5","title":"갱신되지 않은 전광판","description":"취소 알림이 반영되지 않아 MOTH의 옛 입찰가가 남아 있었다."}],"puzzles":[{"id":"auction-seven-p1","title":"최종 유효 최고 입찰자의 닉네임을 입력하세요.","answer":"ORBIT","ignoreCase":true,"hints":["접수표에서 마감 뒤 순번 121을 먼저 제외하세요.","취소 요청 C-19가 가리키는 입찰 B-72도 제외하세요.","240만 원으로 동률인 두 입찰 중 접수 순번이 더 빠른 쪽을 고르세요.","정답은 ORBIT입니다."]}],"messages":[{"id":"auction-seven-m0","author":"경매 운영자","time":"22:00","text":"전광판은 MOTH인데 ORBIT에게 결제 요청이 갔어요. 누구에게 작품을 줘야 하죠?","initial":true},{"id":"auction-seven-m1","author":"ORBIT","time":"22:01","text":"전 마지막에 더 높은 가격을 쓴 적 없어요. 처음 접수한 입찰 그대로예요.","initial":true},{"id":"auction-seven-m2","author":"경매 운영자","time":"22:02","text":"취소는 닉네임이 아니라 입찰 번호에 붙습니다. 다른 물품 기록도 섞여 있으니 조심해요.","initial":false},{"id":"auction-seven-m3","author":"ORBIT","time":"22:03","text":"봉인 원장까지 확인됐나요? 이제 다른 참가자들에게 설명할 수 있겠네요.","initial":false}],"rules":[{"id":"auction-seven-unlock","priority":10,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"auction-seven-p1"},"then":[{"type":"REVEAL_FILE","id":"auction-seven-f4"},{"type":"REVEAL_FILE","id":"auction-seven-f5"},{"type":"APPEND_MESSAGE","id":"auction-seven-m3"}]},{"id":"auction-seven-timer","priority":20,"once":true,"when":{"type":"FILE_READ","id":"auction-seven-f1"},"then":[{"type":"START_TIMER","id":"auction-seven-t1","durationMs":1800}]},{"id":"auction-seven-reply","priority":30,"once":true,"when":{"type":"TIMER_REACHED","id":"auction-seven-t1"},"then":[{"type":"APPEND_MESSAGE","id":"auction-seven-m2"}]}],"endings":[{"id":"auction-seven-good","title":"숫자보다 먼저 도착한 이름","text":"MOTH의 310만 원 입찰은 취소됐고, 400만 원 입찰은 마감 뒤였습니다. 남은 최고가는 ORBIT와 LARK의 240만 원. 먼저 접수된 B-71의 ORBIT가 낙찰자입니다.\n\n전광판은 취소 알림을 처리하지 못해 오래된 순위를 보여줬습니다. ORBIT의 결제 요청과 봉인 확정서가 일치합니다.\n\nORBIT가 메시지를 남겼습니다. “가격 말고 순서를 봐줘서 고마워요.”","revisitable":false},{"id":"auction-seven-retry","title":"가장 큰 숫자의 함정","text":"전광판의 310이나 뒤늦은 400을 그대로 믿었습니다. 높은 가격이라도 취소됐거나 마감 뒤라면 낙찰 대상이 아닙니다.\n\n접수 순번과 취소 입찰 번호를 대조한 뒤 봉인 확정서를 확인해 주세요.","revisitable":true}],"hypotheses":[{"id":"auction-seven-truth","label":"취소·마감·동률 규칙을 적용하면 ORBIT가 정당한 낙찰자다.","endingId":"auction-seven-good","requiredClues":["auction-seven-c1","auction-seven-c2","auction-seven-c4"]},{"id":"auction-seven-guess","label":"MOTH가 가장 큰 금액을 적었으므로 정당한 낙찰자다.","endingId":"auction-seven-retry","requiredClues":[]}]}$case$::jsonb, true);
INSERT INTO ghostdesk.case_versions(version_id, case_id, package, published) VALUES ('encore-last-v1', 'encore-last', $case${"schemaVersion":1,"engineVersion":"ghostdesk-core-1","caseId":"encore-last","versionId":"encore-last-v1","title":"마지막 앙코르","description":"무대는 비었는데 노래는 계속됐다. 사라진 보컬과 네 장의 큐시트가 공연장의 마지막 3분을 숨긴다.","estimatedMinutes":15,"contentWarning":"허구의 사건입니다. 긴장감 있는 상황·실종 암시가 있지만 잔혹한 묘사나 점프 스케어는 없습니다.","files":[{"id":"encore-last-f0","type":"TEXT","title":"무대감독_메모.txt","parentId":null,"visible":true,"text":"공연장 기록 조사 의뢰\n\n앵콜 중 보컬 해온이 무대에서 사라졌지만 관객은 끝까지 노래를 들었다고 합니다. 퇴장문 카메라에는 사람이 지나간 흔적도 없어요.\n\n비공개 기록 암호는 실제 실행된 마지막 네 조명 큐의 카드 번호입니다. 네 자리로 이어 쓰세요. 공연 순서는 실행 로그를, 카드 번호는 큐시트를 보세요. 예정 순서를 그대로 쓰면 틀립니다.\n\n음향 기록과 이동 기록을 함께 확보해야 해온의 마지막 동선을 판단할 수 있습니다.","clueId":"encore-last-c0"},{"id":"encore-last-f1","type":"TEXT","title":"실행_큐_로그.log","parentId":null,"visible":true,"text":"공연 제어기 / 실행 완료 항목\n\n21:56:04  AMBER 실행\n21:56:18  BLUE 실행\n21:56:31  WHITE 실행\n21:56:45  RED 실행\n\n21:56:52  대기 큐 GREEN 취소\n21:57:00  무대 암전\n\n취소된 큐는 실행 순서에 넣지 않습니다.","clueId":"encore-last-c1"},{"id":"encore-last-f2","type":"TEXT","title":"카드별_큐시트.txt","parentId":null,"visible":true,"text":"조명 카드 대조표\n\n카드 1 / WHITE / 객석 방향 빛\n카드 2 / AMBER / 무대 뒤 통로\n카드 3 / RED / 암전 직전 안전 표시\n카드 4 / BLUE / 중앙 스포트라이트\n카드 5 / GREEN / 사용 취소\n\n당초 예정: BLUE → WHITE → AMBER → RED\n무대감독 메모: 공연 중 순서 변경 있음. 실제 실행 로그 우선.","clueId":"encore-last-c2"},{"id":"encore-last-f3","type":"TEXT","title":"관객_제보.txt","parentId":null,"visible":true,"text":"관객 A: 앵콜 첫 소절이 끝날 때 노래가 조금 더 또렷해졌어요.\n관객 B: 정문 쪽에는 아무도 지나가지 않았어요.\n객석 녹음 비교 메모: 21:56:52 이후 들린 기침 소리까지 전날 리허설 녹음과 같은 간격입니다.\n\n제보만으로 누군가가 어디에 있었는지 확정할 수는 없습니다. 공연장에는 정문 외에 무대 뒤 안전 통로도 있습니다.","clueId":"encore-last-c3"},{"id":"encore-last-f4","type":"TEXT","title":"음향_라우팅.log","parentId":"encore-last-vault","visible":false,"text":"음향 장치 / 입력 전환 기록\n\n21:56:52 보컬 무선 마이크 입력 차단\n21:56:52 비상 트랙 REHEARSAL-06 재생 시작\n21:59:10 비상 트랙 재생 완료\n\n담당자 확인: 녹음 파일에는 리허설 때 해온의 기침도 포함됨.\n관객에게 들린 마지막 앵콜은 이 비상 트랙이었습니다.","clueId":"encore-last-c4"},{"id":"encore-last-f5","type":"TEXT","title":"안전통로_인계서.txt","parentId":"encore-last-vault","visible":false,"text":"무대 뒤 안전 통로 / 인계 기록\n\n21:56:49 해온이 현기증을 호소함\n21:56:54 스태프 유진과 안전 통로 통과\n21:57:21 휴게실 도착, 보호자 연락\n22:05:00 회복 후 귀가 안내\n\n서명: 해온 / 유진\n\n정문 카메라에는 이 통로가 찍히지 않습니다. 해온은 무대 위에 남아 있지도, 건물에서 실종되지도 않았습니다.","clueId":"encore-last-c5"},{"id":"encore-last-chat","type":"CHAT_LINK","title":"메신저","parentId":null,"visible":true,"text":""},{"id":"encore-last-vault","type":"FOLDER","title":"비공개 기록","parentId":null,"visible":true,"text":"남은 기록을 대조해 결론을 완성하세요.","puzzleId":"encore-last-p1"}],"clues":[{"id":"encore-last-c0","title":"예정과 실제의 차이","description":"비공개 기록 암호는 실제 조명 실행 순서에 맞춘 카드 번호 네 자리다."},{"id":"encore-last-c1","title":"실행된 네 가지 색","description":"AMBER → BLUE → WHITE → RED 순서로 실행됐다."},{"id":"encore-last-c2","title":"색과 카드 번호","description":"WHITE=1, AMBER=2, RED=3, BLUE=4. 예정 순서는 변경됐다."},{"id":"encore-last-c3","title":"반복된 기침 소리","description":"노래뿐 아니라 기침 간격까지 리허설 녹음과 일치했다."},{"id":"encore-last-c4","title":"마이크 대신 재생된 트랙","description":"마이크 입력이 끊기고 리허설 비상 트랙이 끝까지 재생됐다."},{"id":"encore-last-c5","title":"안전 통로의 두 서명","description":"해온은 유진과 휴게실로 이동했으며 본인 서명으로 인계가 확인됐다."}],"puzzles":[{"id":"encore-last-p1","title":"실행된 조명 큐의 카드 번호를 순서대로 입력하세요.","answer":"2413","ignoreCase":true,"hints":["예정 큐시트와 실제 실행 로그는 순서가 다릅니다.","실행 로그의 색을 AMBER, BLUE, WHITE, RED 순서로 읽으세요.","각 색을 큐시트의 카드 번호로 바꾸고 취소된 GREEN은 빼세요.","정답은 2413입니다."]}],"messages":[{"id":"encore-last-m0","author":"유진","time":"22:06","text":"사람들은 해온이 갑자기 사라졌대. 내가 설명해도 믿질 않아.","initial":true},{"id":"encore-last-m1","author":"음향 기사","time":"22:07","text":"앵콜 때 입력이 전환됐습니다. 비공개 기록에 로그가 있어요.","initial":true},{"id":"encore-last-m2","author":"유진","time":"22:08","text":"예정 큐가 아니라 실제 실행 순서를 봐 줘. 공연 중에 순서가 바뀌었어.","initial":false},{"id":"encore-last-m3","author":"해온","time":"22:10","text":"저는 괜찮아요. 유진이 데려다줬어요. 그때 무대에서 들린 노래는 저도 나중에 들었고요.","initial":false}],"rules":[{"id":"encore-last-unlock","priority":10,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"encore-last-p1"},"then":[{"type":"REVEAL_FILE","id":"encore-last-f4"},{"type":"REVEAL_FILE","id":"encore-last-f5"},{"type":"APPEND_MESSAGE","id":"encore-last-m3"}]},{"id":"encore-last-timer","priority":20,"once":true,"when":{"type":"FILE_READ","id":"encore-last-f1"},"then":[{"type":"START_TIMER","id":"encore-last-t1","durationMs":1800}]},{"id":"encore-last-reply","priority":30,"once":true,"when":{"type":"TIMER_REACHED","id":"encore-last-t1"},"then":[{"type":"APPEND_MESSAGE","id":"encore-last-m2"}]}],"endings":[{"id":"encore-last-good","title":"무대에 남아 있던 것은 목소리","text":"관객은 해온의 목소리를 들었지만, 그 순간 해온이 무대에서 노래한 것은 아니었습니다. 마이크는 차단됐고 리허설 트랙이 대신 재생됐습니다. 반복된 기침도 그 안에 있었습니다.\n\n해온은 유진의 도움으로 안전 통로를 지나 휴게실에 도착했습니다. 카메라에 찍히지 않은 통로와 서명된 인계서가 동선을 설명합니다.\n\n해온은 다음 공연 공지에 한 문장을 더했습니다. “앙코르보다 사람의 안전이 먼저입니다.”","revisitable":false},{"id":"encore-last-retry","title":"목소리를 사람으로 착각하다","text":"노래가 들렸다는 사실만으로 해온이 무대에 남아 있다고 판단했습니다. 소리가 난 위치와 실제 사람의 위치는 같지 않을 수 있습니다.\n\n음향 라우팅 기록과 안전 통로 인계서를 함께 확인하세요.","revisitable":true}],"hypotheses":[{"id":"encore-last-truth","label":"녹음된 앵콜이 재생되는 동안 해온은 안전 통로로 휴게실에 이동했다.","endingId":"encore-last-good","requiredClues":["encore-last-c4","encore-last-c5"]},{"id":"encore-last-guess","label":"노래가 계속 들렸으므로 해온은 끝까지 무대에 남아 있었다.","endingId":"encore-last-retry","requiredClues":[]}]}$case$::jsonb, true);
INSERT INTO ghostdesk.case_versions(version_id, case_id, package, published) VALUES ('monday-loop-v1', 'monday-loop', $case${"schemaVersion":1,"engineVersion":"ghostdesk-core-1","caseId":"monday-loop","versionId":"monday-loop-v1","title":"월요일이 두 번 온 날","description":"섬의 관측소는 사흘째 월요일이다. 같은 문장으로 깨어나는 기록 장치와 바다에 남은 신호를 해독하라.","estimatedMinutes":18,"contentWarning":"허구의 사건입니다. 긴장감 있는 상황·실종 암시가 있지만 잔혹한 묘사나 점프 스케어는 없습니다.","files":[{"id":"monday-loop-f0","type":"TEXT","title":"세_번째_월요일.txt","parentId":null,"visible":true,"text":"월요일 / 관측 담당 나루\n\n아침마다 화면이 같은 문장으로 시작합니다. “오늘은 월요일, 관측을 시작합니다.” 달력도 9월 14일로 돌아와요. 하지만 냉장고의 우유는 줄고 바다의 부표는 더 멀리 떠 있습니다.\n\n비공개 기록은 수신 신호의 영문 해독값으로 잠가 뒀습니다. 세 묶음을 통신 카드로 읽고 공백 없이 쓰세요. 숫자 암호가 아닙니다.\n\n그 안의 외부 관측함은 두 번째 잠금입니다. 먼저 신호부터 풀어 주세요.","clueId":"monday-loop-c0"},{"id":"monday-loop-f1","type":"TEXT","title":"수신_신호.txt","parentId":null,"visible":true,"text":"야간 수신기 / 짧음은 점, 길음은 선\n\n... / --- / ...\n\n각 빗금은 글자 사이의 간격입니다. 점과 선을 개별 글자로 읽지 마세요.\n\n수신기 전원은 별도 배터리라 관측용 PC의 정전 영향을 받지 않습니다.","clueId":"monday-loop-c1"},{"id":"monday-loop-f2","type":"TEXT","title":"통신_카드.txt","parentId":null,"visible":true,"text":"자주 쓰는 모스 부호\n\nA  .-\nN  -.\nO  ---\nS  ...\nT  -\n\n예: ... / .- 는 SA입니다.\n영문으로 해독한 뒤 글자 사이의 공백은 빼세요.","clueId":"monday-loop-c2"},{"id":"monday-loop-f3","type":"TEXT","title":"관측_메모.txt","parentId":null,"visible":true,"text":"종이 노트 / 나루의 필기\n\n첫 번째 월요일: 부표 수신 번호 1084, 파란 밧줄 마름\n두 번째 월요일: 부표 수신 번호 1085, 밧줄 젖음\n세 번째 월요일: 부표 수신 번호 1086, 밧줄에 해초\n\n매번 화면 날짜만 같습니다. 독립된 부표의 번호는 한 번 관측할 때마다 1씩 증가합니다. 왜 종이에는 다음 날이 남는 걸까요?","clueId":"monday-loop-c3"},{"id":"monday-loop-f4","type":"TEXT","title":"복원_작업일지.log","parentId":"monday-loop-vault","visible":false,"text":"관측 PC 자동 복원 설정\n\n정전 후 동작: 백업 SNAP-MONDAY 복원\n복원 대상: 달력 화면, 시작 안내문, 로컬 작업 목록\n복원하지 않는 대상: 종이 노트, 독립 배터리 부표, 실제 시계\n\n정전 감지: 3회\n각 부팅마다 같은 월요일 화면을 다시 불러왔습니다.\n\n외부 관측함 암호는 종이 노트에서 가장 나중에 수신한 네 자리 관측 번호입니다.","clueId":"monday-loop-c4"},{"id":"monday-loop-f5","type":"TEXT","title":"보내지_못한_쪽지.txt","parentId":"monday-loop-vault","visible":false,"text":"정비 담당자가 남긴 쪽지\n\n장치가 계속 재시작하면 화면의 달력을 믿지 마세요. 외부 부표 기록에는 실제 관측 날짜가 남습니다.\n\n종이 노트의 마지막 번호로 외부 관측함을 열면 이 세 번이 같은 날인지 다른 날인지 확인할 수 있습니다.\n\n신호는 제가 정비선에서 보낸 SOS였습니다. 통신이 복구된 뒤에는 구조 요청을 이미 전달했습니다. 누구도 섬에 혼자 남겨두지 않았습니다.","clueId":"monday-loop-c5"},{"id":"monday-loop-chat","type":"CHAT_LINK","title":"메신저","parentId":null,"visible":true,"text":""},{"id":"monday-loop-vault","type":"FOLDER","title":"비공개 기록","parentId":null,"visible":true,"text":"남은 기록을 대조해 결론을 완성하세요.","puzzleId":"monday-loop-p1"},{"id":"monday-loop-inner","type":"FOLDER","title":"외부 관측함","parentId":"monday-loop-vault","visible":true,"text":"달력 밖에서 남은 기록.","puzzleId":"monday-loop-p2"},{"id":"monday-loop-final","type":"TEXT","title":"부표_원본_기록.txt","parentId":"monday-loop-inner","visible":false,"text":"독립 배터리 관측 부표 / 원본 수신 기록\n\n09-14 월요일 / 1084 / 정상 수신\n09-15 화요일 / 1085 / 정상 수신\n09-16 수요일 / 1086 / 정상 수신\n\n관측 PC와 전원·저장장치를 공유하지 않습니다. 세 기록은 서로 다른 날에 생성됐고 재전송이 아닙니다.\n\n종이 노트의 번호와 순서가 일치합니다. 바다는 세 번의 아침을 기록했습니다.","clueId":"monday-loop-final-clue"}],"clues":[{"id":"monday-loop-c0","title":"달력과 생활의 모순","description":"화면은 월요일로 돌아가지만 현실의 물건과 바다는 달라지고 있다."},{"id":"monday-loop-c1","title":"세 묶음의 구조 신호","description":"짧게 세 번 / 길게 세 번 / 짧게 세 번. 묶음마다 한 글자다."},{"id":"monday-loop-c2","title":"모스 통신 카드","description":"S는 점 세 개, O는 선 세 개. 빗금은 글자 간격이다."},{"id":"monday-loop-c3","title":"계속 증가하는 관측 번호","description":"같은 달력 표시와 달리 외부 관측 번호는 1084, 1085, 1086으로 증가했다."},{"id":"monday-loop-c4","title":"매 부팅마다 복원되는 월요일","description":"정전 때 월요일 백업 화면만 복원됐고 외부 관측에는 영향을 주지 않았다."},{"id":"monday-loop-c5","title":"화면 밖의 날짜를 확인할 것","description":"달력 복원과 무관한 외부 부표 원본 날짜가 최종 확인 수단이다."},{"id":"monday-loop-final-clue","title":"달력 밖의 관측 일련번호","description":"외부 부이는 서로 다른 세 날짜에 1084·1085·1086을 기록했다. 시간은 앞으로 흘렀다."}],"puzzles":[{"id":"monday-loop-p1","title":"세 묶음의 수신 신호를 영문으로 해독해 입력하세요.","answer":"SOS","ignoreCase":true,"hints":["빗금으로 나눈 세 묶음이 각각 한 글자입니다.","통신 카드에서 점 세 개와 선 세 개에 해당하는 글자를 찾으세요.","첫 글자와 마지막 글자는 S, 가운데는 O입니다.","정답은 SOS입니다."]},{"id":"monday-loop-p2","title":"종이 노트의 마지막 관측 번호 네 자리를 입력하세요.","answer":"1086","ignoreCase":false,"hints":["날짜가 아니라 종이 노트의 관측 번호를 보세요.","첫 번째, 두 번째, 세 번째 월요일 순서입니다.","가장 나중에 수신한 값은 1086입니다.","정답은 1086입니다."]}],"messages":[{"id":"monday-loop-m0","author":"나루","time":"08:00","text":"또 월요일이야. 어제도 이 대화를 했던 것 같은데.","initial":true},{"id":"monday-loop-m1","author":"정비선","time":"08:02","text":"우리 쪽 수신 번호는 계속 늘고 있어요. 별도 배터리 장치를 확인해 보세요.","initial":true},{"id":"monday-loop-m2","author":"나루","time":"08:04","text":"점과 선을 한 덩어리로 읽는 게 아니었네. 빗금이 글자를 나눠 주는구나.","initial":false},{"id":"monday-loop-m3","author":"정비선","time":"08:06","text":"첫 잠금이 열렸군요. 이제 관측함의 두 번째 잠금과 실제 날짜를 확인하세요.","initial":false}],"rules":[{"id":"monday-loop-unlock","priority":10,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"monday-loop-p1"},"then":[{"type":"REVEAL_FILE","id":"monday-loop-f4"},{"type":"REVEAL_FILE","id":"monday-loop-f5"},{"type":"APPEND_MESSAGE","id":"monday-loop-m3"}]},{"id":"monday-loop-timer","priority":20,"once":true,"when":{"type":"FILE_READ","id":"monday-loop-f1"},"then":[{"type":"START_TIMER","id":"monday-loop-t1","durationMs":1800}]},{"id":"monday-loop-reply","priority":30,"once":true,"when":{"type":"TIMER_REACHED","id":"monday-loop-t1"},"then":[{"type":"APPEND_MESSAGE","id":"monday-loop-m2"}]},{"id":"monday-loop-unlock-final","priority":15,"once":true,"when":{"type":"PUZZLE_SOLVED","id":"monday-loop-p2"},"then":[{"type":"REVEAL_FILE","id":"monday-loop-final"}]}],"endings":[{"id":"monday-loop-good","title":"다음 날은 이미 와 있었다","text":"반복된 것은 하루가 아니라 월요일의 화면이었습니다. 정전마다 복원 작업이 오래된 달력과 안내문을 다시 불러왔습니다.\n\n독립 배터리 부표는 9월 14일, 15일, 16일을 차례로 기록했습니다. 관측 번호도 1084에서 1086으로 증가했습니다. 종이 노트와 외부 원본이 같은 방향을 가리킵니다.\n\n나루는 모니터 옆에 새 쪽지를 붙였습니다. “오늘 날짜는 바다와 함께 확인할 것.” 그리고 처음으로 수요일의 기록을 저장했습니다.","revisitable":false},{"id":"monday-loop-retry","title":"같은 문장이 같은 하루는 아니다","text":"같은 인사와 날짜를 보고 시간이 반복된다고 판단했습니다. 하지만 그 결론은 줄어든 우유와 달라진 관측 번호를 설명하지 못합니다.\n\n비공개 기록의 복원 작업일지와 외부 관측함의 원본 날짜를 끝까지 대조해 주세요.","revisitable":true}],"hypotheses":[{"id":"monday-loop-truth","label":"하루가 반복된 것이 아니라, 정전마다 월요일 화면이 백업에서 복원됐다.","endingId":"monday-loop-good","requiredClues":["monday-loop-c3","monday-loop-c4","monday-loop-final-clue"]},{"id":"monday-loop-guess","label":"섬의 시간 자체가 월요일에 갇혀 같은 하루가 반복되고 있다.","endingId":"monday-loop-retry","requiredClues":[]}]}$case$::jsonb, true);
INSERT INTO ghostdesk.schema_migrations(version) VALUES (2);
